from ejemplos_v2 import EXTRA
EJEMPLOS = EJEMPLOS + EXTRA


def construir(ruta):
    with open(ruta, "w", encoding="utf-8") as f:
        for categoria, turnos in EJEMPLOS:
            assert len(turnos) % 2 == 0, turnos[0]
            mensajes = [{"role": "system", "content": SYSTEM}]
            for i, texto in enumerate(turnos):
                mensajes.append({"role": "user" if i % 2 == 0 else "assistant", "content": texto})
            f.write(json.dumps({"categoria": categoria, "messages": mensajes}, ensure_ascii=False) + "\n")
    return len(EJEMPLOS)


if __name__ == "__main__":
    salida = sys.argv[1] if len(sys.argv) > 1 else "nati_dataset.jsonl"
    print(construir(salida), "conversaciones ->", salida)
